@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings

<nav class="nav nav-pills flex-column settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>@section
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => ""
    };
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings
@using sv_330eed365a7e4356a72f430331f3fed8.Models

<div class="profile-section">
    <h4 class="mb-4">Profile Settings</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            Profile saved successfully!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="DisplayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="Email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="Bio"></textarea>
            </div>
        </div>
        <div class="col-md-4 text-center">
            <div class="avatar-preview mb-3">
                <img src="@AvatarUrl" alt="Avatar" class="rounded-circle img-fluid" style="width:120px;height:120px;object-fit:cover;" />
            </div>
            <div class="mb-3">
                <label class="form-label">Avatar URL</label>
                <input type="url" class="form-control form-control-sm" @bind="AvatarUrl" />
            </div>
        </div>
    </div>

    <div class="d-flex gap-2">
        <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
    </div>
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName = "";
    private string Email = "";
    private string Bio = "";
    private string AvatarUrl = "";
    private bool ShowSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !_initialized)
        {
            LoadFromProfile();
            _initialized = true;
        }
    }

    private bool _initialized;

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        Bio = Profile.Bio;
        AvatarUrl = Profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
    }

    private void DiscardChanges()
    {
        LoadFromProfile();
        ShowSuccess = false;
    }
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings
@using sv_330eed365a7e4356a72f430331f3fed8.Models

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            Preferences saved successfully!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="mb-4">
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="EmailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="PushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-3">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="WeeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <h5 class="mb-3">Muted Channels</h5>
    <div class="mb-4">
        @foreach (var channel in AvailableChannels)
        {
            <div class="form-check mb-2">
                <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                       checked="@MutedChannels.Contains(channel)"
                       @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
            </div>
        }
    </div>

    <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool EmailNotifications;
    private bool PushNotifications;
    private bool WeeklyDigest;
    private List<string> MutedChannels = new();
    private bool ShowSuccess;

    private static readonly string[] AvailableChannels = { "general", "marketing", "engineering", "announcements", "random" };

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !_initialized)
        {
            EmailNotifications = Prefs.EmailNotifications;
            PushNotifications = Prefs.PushNotifications;
            WeeklyDigest = Prefs.WeeklyDigest;
            MutedChannels = new List<string>(Prefs.MutedChannels);
            _initialized = true;
        }
    }

    private bool _initialized;

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !MutedChannels.Contains(channel))
            MutedChannels.Add(channel);
        else if (!muted)
            MutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(EmailNotifications, PushNotifications, WeeklyDigest, new List<string>(MutedChannels));
        await OnSave.InvokeAsync(updated);
        ShowSuccess = true;
    }
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings

<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center" style="cursor:pointer;" @onclick="ToggleExpanded">
        <h5 class="mb-0">Change Password</h5>
        <span>@(IsExpanded ? "▲" : "▼")</span>
    </div>
    @if (IsExpanded)
    {
        <div class="card-body">
            @if (!string.IsNullOrEmpty(ErrorMessage))
            {
                <div class="alert alert-danger">@ErrorMessage</div>
            }
            @if (ShowSuccess)
            {
                <div class="alert alert-success">Password updated successfully!</div>
            }

            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="CurrentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="NewPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="ConfirmPassword" />
            </div>
            <button class="btn btn-warning" @onclick="UpdatePassword" disabled="@IsProcessing">
                @(IsProcessing ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }

    private bool IsExpanded;
    private string CurrentPassword = "";
    private string NewPassword = "";
    private string ConfirmPassword = "";
    private string? ErrorMessage;
    private bool ShowSuccess;
    private bool IsProcessing;

    private void ToggleExpanded() => IsExpanded = !IsExpanded;

    private async Task UpdatePassword()
    {
        ErrorMessage = null;
        ShowSuccess = false;

        if (string.IsNullOrWhiteSpace(CurrentPassword) || string.IsNullOrWhiteSpace(NewPassword))
        {
            ErrorMessage = "All fields are required.";
            return;
        }
        if (NewPassword != ConfirmPassword)
        {
            ErrorMessage = "New password and confirmation do not match.";
            return;
        }
        if (NewPassword.Length < 8)
        {
            ErrorMessage = "New password must be at least 8 characters.";
            return;
        }

        IsProcessing = true;
        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
        IsProcessing = false;
        ShowSuccess = true;
        CurrentPassword = "";
        NewPassword = "";
        ConfirmPassword = "";
    }
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings
@using sv_330eed365a7e4356a72f430331f3fed8.Models

<div class="card">
    <div class="card-header">
        <h5 class="mb-0">Active Sessions</h5>
    </div>
    <div class="card-body p-0">
        <table class="table table-hover mb-0">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge bg-success">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

@* Confirmation Dialog *@
@if (SessionToRevoke is not null)
{
    <div class="modal fade show d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@SessionToRevoke.Device</strong> in @SessionToRevoke.Location?</p>
                    <p class="text-muted">This will sign out that device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public List<ActiveSession> Sessions { get; set; } = new();
    [Parameter] public string CurrentSessionId { get; set; } = "session-1";
    [Parameter] public EventCallback<string> OnRevoke { get; set; }

    private ActiveSession? SessionToRevoke;

    private void PromptRevoke(ActiveSession session) => SessionToRevoke = session;
    private void CancelRevoke() => SessionToRevoke = null;

    private async Task ConfirmRevoke()
    {
        if (SessionToRevoke is not null)
        {
            await OnRevoke.InvokeAsync(SessionToRevoke.Id);
            SessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings
@using sv_330eed365a7e4356a72f430331f3fed8.Models

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    <ChangePasswordPanel OnChangePassword="HandleChangePassword" />

    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <h5 class="mb-1">Two-Factor Authentication</h5>
                <p class="text-muted mb-0">
                    @if (TwoFactorEnabled)
                    {
                        <span class="badge bg-success me-2">Enabled</span>
                        <span>Your account is protected with 2FA.</span>
                    }
                    else
                    {
                        <span class="badge bg-warning me-2">Disabled</span>
                        <span>Enable 2FA for additional security.</span>
                    }
                </p>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@TwoFactorEnabled" @onchange="Toggle2FA" />
            </div>
        </div>
    </div>

    @if (Settings?.LastPasswordChange is not null)
    {
        <p class="text-muted mb-4">
            <small>Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</small>
        </p>
    }

    <ActiveSessionsTable Sessions="@(Settings?.Sessions ?? new())" OnRevoke="HandleRevoke" />
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }

    private bool TwoFactorEnabled;

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            TwoFactorEnabled = Settings.TwoFactorEnabled;
        }
    }

    private void Toggle2FA(ChangeEventArgs e)
    {
        TwoFactorEnabled = (bool)(e.Value ?? false);
    }

    private async Task HandleChangePassword((string Current, string New) passwords)
    {
        await OnChangePassword.InvokeAsync(passwords);
    }

    private async Task HandleRevoke(string sessionId)
    {
        await OnRevokeSession.InvokeAsync(sessionId);
    }
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings

<div class="card">
    <div class="card-header">
        <h6 class="mb-0">Live Preview</h6>
    </div>
    <div class="card-body @GetPreviewClasses()" style="@GetPreviewStyles()">
        <h5 style="@GetFontStyle()">Settings Dashboard</h5>
        <p style="@GetFontStyle()">This is how your content will look with the selected appearance settings.</p>
        <button class="btn @GetButtonClass() btn-sm">Sample Button</button>
        <span class="badge @GetBadgeClass() ms-2">Badge</span>
        @if (CompactMode)
        {
            <p class="mt-2 mb-0"><small class="text-muted">Compact mode: reduced spacing</small></p>
        }
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public bool CompactMode { get; set; }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        if (CompactMode) classes.Add("p-2");
        else classes.Add("p-3");
        return string.Join(" ", classes);
    }

    private string GetPreviewStyles()
    {
        var bg = Theme switch
        {
            "Dark" => "background-color: #1a1a2e; color: #e0e0e0;",
            "System" => "background-color: #f0f0f0; color: #333; border-left: 3px solid #6c757d;",
            _ => "background-color: #ffffff; color: #212529; border: 1px solid #dee2e6;"
        };
        return bg;
    }

    private string GetFontStyle() => FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string GetButtonClass() => Theme == "Dark" ? "btn-light" : "btn-primary";
    private string GetBadgeClass() => Theme == "Dark" ? "bg-light text-dark" : "bg-primary";
}

@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings
@using sv_330eed365a7e4356a72f430331f3fed8.Models

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    @if (ShowSuccess)
    {
        <div class="alert alert-success alert-dismissible fade show" role="alert">
            Appearance settings saved!
            <button type="button" class="btn-close" @onclick="() => ShowSuccess = false"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <div class="mb-4">
                <label class="form-label fw-bold">Theme</label>
                <div>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(Theme == theme)"
                                   @onchange="() => Theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
