+        }
+
+        IsProcessing = true;
+        await OnChangePassword.InvokeAsync((CurrentPassword, NewPassword));
+        IsProcessing = false;
+        ShowSuccess = true;
+        CurrentPassword = "";
+        NewPassword = "";
+        ConfirmPassword = "";
+    }
+}
