@page "/settings"
@namespace sv_330eed365a7e4356a72f430331f3fed8.Components.Pages.Settings
@using sv_330eed365a7e4356a72f430331f3fed8.Models
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <div class="settings-layout">
        <aside class="settings-nav">
            <SettingsSidebar ActiveSection="@ActiveSection" OnSectionSelected="SetActiveSection" />
        </aside>
        <main class="settings-content">
            @if (IsLoading)
            {
                <div class="d-flex justify-content-center p-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (ActiveSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@Profile" OnSave="SaveProfile" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@NotificationPrefs" OnSave="SaveNotifications" />
                        break;
                    case "Security":
                        <SecuritySection Settings="@Security" OnChangePassword="ChangePassword" OnRevokeSession="RevokeSession" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@Appearance" OnSave="SaveAppearance" />
                        break;
                }
            }
        </main>
    </div>
</div>

@code {
    private string ActiveSection = "Profile";
    private bool IsLoading = true;

    private UserProfile? Profile;
    private NotificationPrefs? NotificationPrefs;
    private SecuritySettings? Security;
    private AppearanceSettings? Appearance;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        IsLoading = false;
    }

    private async Task LoadAllSettings()
    {
        Profile = await SettingsService.GetProfileAsync();
        NotificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        Security = await SettingsService.GetSecuritySettingsAsync();
        Appearance = await SettingsService.GetAppearanceAsync();
    }

    private void SetActiveSection(string section) => ActiveSection = section;

    private async Task SaveProfile(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        Profile = profile;
    }

    private async Task SaveNotifications(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        NotificationPrefs = prefs;
    }

    private async Task ChangePassword((string Current, string New) passwords)
    {
